{"description":"### Proposed Code for Functional `PollForJobPods`

Here is the exact code we will inject into `internal/k8s/logs/client.go` to replace the imperative `PollForJobPods` function.

```go
package logs

import (
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	A "github.com/IBM/fp-go/v2/array"
	E "github.com/IBM/fp-go/v2/either"
	fperrors "github.com/IBM/fp-go/v2/errors"
	F "github.com/IBM/fp-go/v2/function"
	IO "github.com/IBM/fp-go/v2/io"
	IOE "github.com/IBM/fp-go/v2/ioeither"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
	"k8s.io/client-go/tools/clientcmd"
)

// ... CreateK8sClient remains the same ...

var errPodsNotReady = errors.New("pods not ready yet")

// checkTimeout safely checks if we have exceeded the 30-second poll window.
func checkTimeout(deadline time.Time) E.Either[error, time.Time] {
	return F.Pipe1(
		deadline,
		E.FromPredicate(
			func(d time.Time) bool { return time.Now().Before(d) },
			func(_ time.Time) error { return fmt.Errorf("timeout waiting for pods to spawn") },
		),
	)
}

// fetchPodsAttempt performs a single K8s API call to list pods by job-name.
func fetchPodsAttempt(ctx LogContext) IOE.IOEither[error, *corev1.PodList] {
	return F.Pipe1(
		IOE.TryCatchError(func() (*corev1.PodList, error) {
			return ctx.Client.CoreV1().Pods(ctx.Namespace).List(
				ctx.Context,
				metav1.ListOptions{LabelSelector: fmt.Sprintf("job-name=%s", ctx.Name)},
			)
		}),
		IOE.MapLeft[*corev1.PodList](fperrors.OnError("failed to list job pods")),
	)
}

// checkPodList checks if the returned list contains any pods. If empty, it
// fails with errPodsNotReady to signal the recursive loop to continue.
func checkPodList(list *corev1.PodList) E.Either[error, *corev1.PodList] {
	return F.Pipe2(
		list.Items,
		E.FromPredicate(
			A.IsNonEmpty[corev1.Pod],
			func(_ []corev1.Pod) error { return errPodsNotReady },
		),
		E.Map[error](func(_ []corev1.Pod) *corev1.PodList { return list }),
	)
}

// sleepAndRecurse sleeps for 2 seconds and calls pollLoop again.
func sleepAndRecurse(ctx LogContext, deadline time.Time) IOE.IOEither[error, *corev1.PodList] {
	return F.Pipe2(
		IO.Delay[struct{}](2*time.Second)(IO.Of(struct{}{})),
		IOE.FromIO[error, struct{}],
		IOE.Chain(func(_ struct{}) IOE.IOEither[error, *corev1.PodList] {
			return pollLoop(ctx, deadline)
		}),
	)
}

// pollLoop is the purely functional recursive polling engine.
func pollLoop(ctx LogContext, deadline time.Time) IOE.IOEither[error, *corev1.PodList] {
	return F.Pipe5(
		checkTimeout(deadline),
		IOE.FromEither[error, time.Time],
		IOE.Chain(func(_ time.Time) IOE.IOEither[error, *corev1.PodList] {
			return fetchPodsAttempt(ctx)
		}),
		IOE.ChainEitherK(checkPodList),
		IOE.CatchAll(func(err error) IOE.IOEither[error, *corev1.PodList] {
			// If the error is exactly errPodsNotReady, we sleep and recurse.
			// Otherwise (fatal API error or Timeout), we bubble the error up to abort.
			if errors.Is(err, errPodsNotReady) {
				return sleepAndRecurse(ctx, deadline)
			}
			return IOE.Left[error, *corev1.PodList](err)
		}),
	)
}

// PollForJobPods initializes the deadline and kicks off the recursive polling loop.
func PollForJobPods(ctx LogContext) IOE.IOEither[error, *corev1.PodList] {
	return pollLoop(ctx, time.Now().Add(30*time.Second))
}

